@pytest.fixture
def page(context, browser_pool, dom_cache, healing_engine, intelligent_runtime, request) -> Page:
    """Playwright Page fixture with automatic Intelligent Runtime integration.
    
    This fixture automatically wraps the standard Playwright page with intelligent
    runtime capabilities when IntelligentRuntime is available, ensuring:
    - DOM Snapshot reuse decisions
    - Locator Repository integration
    - Healing Engine availability
    - Runtime Metrics collection
    - Timeline tracking
    
    The integration is transparent - tests don't need to change their code.
    """
    p = None
    use_browser_pool = PHOENIX_AVAILABLE and browser_pool
    
    if use_browser_pool:
        # Get page from browser pool
        browser_id = "browser_0"  # Assume first browser
        page_id, p = browser_pool.get_page(context, browser_id)
        p.set_default_timeout(ACTION_TIMEOUT_MS)
        p.set_default_navigation_timeout(NAVIGATION_TIMEOUT_MS)
        p.on("dialog", lambda dialog: dialog.dismiss())
        
        # Store DOM cache reference on page for use in tests
        p._phoenix_dom_cache = dom_cache
        p._phoenix_healing_engine = healing_engine
    else:
        p = context.new_page()
        p.set_default_timeout(ACTION_TIMEOUT_MS)
        p.set_default_navigation_timeout(NAVIGATION_TIMEOUT_MS)
        p.on("dialog", lambda dialog: dialog.dismiss())
    
    # Always attempt intelligent page wrapping if IntelligentRuntime is available
    if intelligent_runtime:
        try:
            from phoenix.execution.intelligent_page import create_intelligent_page as create_intelligent_page
            test_name = request.node.name if hasattr(request, 'node') else "orange_test"
            execution_id = getattr(intelligent_runtime, 'execution_id', '')
            project_name = getattr(intelligent_runtime, 'project_name', 'orange')
            
            print(f"[INTELLIGENT PAGE] Wrapping page for test: {test_name}")
            print(f"[INTELLIGENT PAGE] Project: {project_name}, Execution ID: {execution_id}")
            
            p = create_intelligent_page(
                page=p,
                intelligent_runtime=intelligent_runtime,
                project_name=project_name,
                test_name=test_name,
                execution_id=execution_id
            )
            
            print(f"[INTELLIGENT PAGE] Page successfully wrapped with intelligent runtime")
        except Exception as e:
            print(f"[INTELLIGENT PAGE] Failed to wrap page with intelligent runtime: {e}")
            print(f"[INTELLIGENT PAGE] Falling back to standard Playwright page")
            # Continue with standard page if wrapping fails
    else:
        print("[INTELLIGENT PAGE] Intelligent Runtime not available, using standard Playwright page")
    
    yield p
    
    # Cleanup
    if not use_browser_pool:
        with suppress(Exception):
            p.close()


